    <!-- ==========================================
         SLIDE 2: PROBLEM — FLOOD IRRIGATION
         ========================================== -->
    <section class="slide problem-slide" id="slide-2">
        <div class="orb orb-amber" style="width:35vw;height:35vw;top:-15%;right:5%;opacity:0.35;"></div>

        <div class="slide-content">
            <div class="section-label">Problem</div>

            <h2 class="reveal">
                Current Agents Use "Flood Irrigation" —<br>
                <span style="color: var(--accent-red);">Indiscriminate Knowledge Injection</span>
            </h2>

            <div class="divider reveal"></div>

            <!-- Three paradigms -->
            <div class="problem-cols reveal">
                <div class="problem-col">
                    <div class="problem-col-badge badge-traj">Paradigm 1</div>
                    <h3>Trajectory Imitation</h3>
                    <p>Blindly copies gold action sequences without adapting to what the agent already knows.</p>
                    <div class="example-method">e.g., ReAct</div>
                </div>
                <div class="problem-col">
                    <div class="problem-col-badge badge-trial">Paradigm 2</div>
                    <h3>Trial-and-Error Refinement</h3>
                    <p>Always invokes costly reflection regardless of whether a step was already correct.</p>
                    <div class="example-method">e.g., Reflexion</div>
                </div>
                <div class="problem-col">
                    <div class="problem-col-badge badge-know">Paradigm 3</div>
                    <h3>Knowledge-Augmented</h3>
                    <p>Injects domain knowledge at every step — 100% usage — even when unnecessary.</p>
                    <div class="example-method">e.g., KnowAgent, WKM</div>
                </div>
            </div>

            <!-- Shared failure + contrast -->
            <div class="contrast-row reveal">
                <div class="contrast-box bad">
                    <div class="contrast-label">❌ Flood Irrigation</div>
                    <p style="font-size: var(--small-size); line-height:1.45;">
                        Pattern collapse on unexpected inputs &nbsp;·&nbsp;
                        Fragile planning &nbsp;·&nbsp;
                        High inference cost &nbsp;·&nbsp;
                        No situational judgment
                    </p>
                </div>
                <div class="contrast-box good">
                    <div class="contrast-label">✓ Human Metacognition</div>
                    <p style="font-size: var(--small-size); line-height:1.45;">
                        Assess difficulty first &nbsp;·&nbsp;
                        Act directly when confident &nbsp;·&nbsp;
                        Reflect when uncertain &nbsp;·&nbsp;
                        Seek help only when needed
                    </p>
                </div>
            </div>
        </div>

        <div class="slide-num">02 / 08</div>
    </section>

    <!-- ==========================================
         SLIDE 3: THREE THINKING MODES — FLOW DIAGRAM
         ========================================== -->
    <section class="slide modes-slide" id="slide-3">
        <div class="orb orb-cyan" style="width:30vw;height:30vw;bottom:0%;left:-5%;opacity:0.3;"></div>

        <div class="slide-content">
            <div class="section-label">Framework</div>

            <h2 class="reveal">
                Three Situational Modes:<br>
                <span class="accent-cyan">Fast</span> · <span class="accent-amber">Slow</span> · <span class="accent-green">Knowledgeable</span> Thinking
            </h2>

            <div class="divider reveal"></div>

            <!-- Flow diagram: Decision node → branches → mode cards -->
            <div class="flow-diagram reveal-scale">

                <!-- Left: Decision diamond -->
                <div class="flow-decision">
                    <div class="decision-diamond">
                        <div class="decision-text">At each<br>decision<br>step</div>
                    </div>
                </div>

                <!-- Middle: Connectors with criteria labels -->
                <div class="flow-connectors">
                    <div class="flow-connector">
                        <div class="connector-label" style="color: var(--accent-cyan);">Direct match</div>
                        <div class="connector-line" style="background: linear-gradient(90deg, var(--accent-cyan), transparent);"></div>
                    </div>
                    <div class="flow-connector">
                        <div class="connector-label" style="color: var(--accent-amber);">Wrong → corrects on reflection</div>
                        <div class="connector-line" style="background: linear-gradient(90deg, var(--accent-amber), transparent);"></div>
                    </div>
                    <div class="flow-connector">
                        <div class="connector-label" style="color: var(--accent-green);">Cannot correct even after reflection</div>
                        <div class="connector-line" style="background: linear-gradient(90deg, var(--accent-green), transparent);"></div>
                    </div>
                </div>

                <!-- Right: Mode cards -->
                <div class="mode-cards">
                    <div class="mode-card fast">
                        <div class="mode-icon">⚡</div>
                        <div class="mode-info">
                            <h3>Fast Thinking</h3>
                            <p>Agent directly produces the correct action with minimal deliberation</p>
                        </div>
                        <div class="mode-token">&lt;ACT&gt;</div>
                    </div>
                    <div class="mode-card slow">
                        <div class="mode-icon">🔄</div>
                        <div class="mode-info">
                            <h3>Slow Thinking</h3>
                            <p>Agent self-corrects through reflection before committing to action</p>
                        </div>
                        <div class="mode-token">&lt;REF&gt;</div>
                    </div>
                    <div class="mode-card know">
                        <div class="mode-icon">📚</div>
                        <div class="mode-info">
                            <h3>Knowledgeable Thinking</h3>
                            <p>Agent retrieves external knowledge — only when strictly necessary</p>
                        </div>
                        <div class="mode-token">&lt;KNO&gt;</div>
                    </div>
                </div>

            </div><!-- /flow-diagram -->

        </div>

